style.css:
@-moz-document domain("my.wgu.edu") {
/* ===== COLORS ===== */

:root{
    --bg: #fdeff5;
    --card: #fff7fa;
    --accent: #f7a6cf;
    --accent-dark: #eb87bd;
    --text: #444444;
}

/* ===== MAIN BACKGROUND ===== */

body,
html {
    background: var(--bg) !important;
    color: var(--text) !important;
}

/* ===== HEADER ===== */

header,
nav,
[class*="header"],
[class*="navbar"] {
    background: #f7c4dc !important;
    border: none !important;
}

/* ===== BUTTONS ===== */

button,
.btn,
input[type="submit"] {
    background: var(--accent) !important;
    border: none !important;
    color: white !important;
    border-radius: 12px !important;
}

/* Hover */

button:hover,
.btn:hover {
    background: var(--accent-dark) !important;
}

/* ===== CARDS ===== */

[class*="card"],
[class*="Card"],
[class*="panel"],
[class*="Panel"] {
    background: var(--card) !important;
    border: 1px solid #f5d5e5 !important;
    border-radius: 18px !important;
    box-shadow: 0 2px 10px rgba(255,180,210,.15) !important;
}

/* ===== COURSE AREA ===== */

[class*="course"],
[class*="Course"] {
    background: white !important;
}

/* ===== LINKS ===== */

a {
    color: #d9629c !important;
}

/* ===== PROGRESS BARS ===== */

progress,
[role="progressbar"] {
    accent-color: #f49bc8 !important;
}

/* ===== ROUND EVERYTHING ===== */

div,
button,
input,
select {
    border-radius: 12px !important;
}
}
